const icon = name => `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.book}</svg>`;
const esc = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials = name => name.split(' ').map(n=>n[0]).slice(0,2).join('');
const dateKey = (d) => d===undefined ? store.today() : `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const formatDate = (value,options={month:'short',day:'numeric'}) => new Date(`${value}T12:00:00`).toLocaleDateString('en-IN',options);
const duration = value => value>=60?`${Math.floor(value/60)}h${value%60?` ${value%60}m`:''}`:`${value} min`;
const button = (label,action,style='secondary',attrs='') => `<button type="button" class="button ${style}" data-action="${action}" ${attrs}>${label}</button>`;
const badge = (text,color='') => `<span class="badge ${color}">${esc(text)}</span>`;
const empty = (title,copy,action='') => `<div class="empty-state">${icon('leaf')}<h3>${esc(title)}</h3><p>${esc(copy)}</p>${action}</div>`;
function sidebarPreferences(){
 try{const saved=JSON.parse(localStorage.getItem('learnio.sidebar')||'{}');return {sidebarWidth:clampSidebarWidth(saved?.width),sidebarCollapsed:saved?.collapsed===true};}catch(_){return {sidebarWidth:250,sidebarCollapsed:false};}
}
function clampSidebarWidth(value){return Math.round(Math.max(220,Math.min(400,Number.isFinite(Number(value))?Number(value):250)));}
