function notice(message) { const t=document.querySelector('#toast');t.textContent=message;t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,4500); }
function saved(result,message,next) { if(!result?.ok){notice(result?.error||'That change could not be saved. Please try again.');return false;}if(next)next(result);if(message)notice(message);return true; }
function themePreference(){try{return localStorage.getItem('learnio.theme')||'system';}catch(_){return 'system';}}
function applyTheme(p){document.documentElement.dataset.theme=p==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):p;}
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>applyTheme(themePreference()));

