 const days=Array.from({length:dayCount},(_,i)=>{const d=new Date(first);d.setDate(d.getDate()+i);const key=dateKey(d),items=tasks.filter(t=>t.date===key),matching=items.filter(match),done=matching.filter(t=>t.completedAt).length;return `<div class="calendar-day ${items.length?'has-sessions':''} ${d.getMonth()!==month-1?'outside':''} ${key===dateKey()?'today':''} ${items.length&&!matching.length?'filtered-out':''}"><button type="button" class="calendar-day-head" data-calendar-day="${key}" aria-label="Open ${formatDate(key,{weekday:'long',month:'long',day:'numeric',year:'numeric'})}, ${matching.length} matching sessions"><span class="calendar-date">${d.getDate()}</span><span class="day-workload">${matching.length?duration(matching.reduce((n,t)=>n+t.minutes,0)):key===dateKey()?'Today':''}</span></button><div class="calendar-dots" aria-hidden="true">${[...new Set(matching.map(t=>t.type))].map(type=>`<i class="activity-${type}"></i>`).join('')}</div>${matching.slice(0,2).map(t=>`<button class="calendar-event activity-${t.type} ${t.completedAt?'complete':''}" data-item="${t.itemId}" data-task-id="${t.id}" aria-label="${esc(t.title)}, ${formatDate(key)}, ${t.startTime}, ${t.completedAt?'completed':'planned'}"><span>${icon(activityType(t.type).icon)} ${t.startTime} ${t.completedAt?icon('check'):''}</span><strong>${esc(t.title)}</strong></button>`).join('')}${matching.length>2?`<button type="button" class="calendar-more" data-calendar-day="${key}">+${matching.length-2} more</button>`:!items.length?'<small class="calendar-open">Nothing scheduled</small>':!matching.length?'<small class="calendar-open">No matching sessions</small>':''}${matching.length?`<div class="day-completion" aria-label="${done} of ${matching.length} matching sessions complete"><span style="width:${100*done/matching.length}%"></span></div>`:''}</div>`;}).join('');
