 return head('Practice and scheduled quizzes.','Manage your quizzes and review saved attempts in one place.',button('Schedule quiz','schedule-quiz'))+`<section class="panel"><h2>Scheduled quizzes</h2>${scheduled.map(item=>{const task=tasks.find(t=>t.itemId===item.id),attempt=attempts.find(a=>a.itemId===item.id&&a.status!=='abandoned'),locked=!!(item.completedAt||item.cancelledAt||attempt||!task?.fixed);return `<article class="assessment-row"><div><strong>${esc(item.title)}</strong><p class="muted">${item.cancelledAt?'Cancelled · history retained':task?`${formatDate(task.date)} · ${task.startTime} · ${duration(task.minutes)}`:'Not allocated'} · ${esc(item.difficulty||'Beginner')}</p>${badge(item.cancelledAt?'Cancelled':item.completedAt?'Completed':attempt?.status==='in-progress'?'In progress':'Scheduled',item.completedAt?'green':'')}</div><div class="actions">${item.cancelledAt?'':`<button class="button ${locked?'secondary':'primary'}" data-item="${item.id}">${attempt?'Open attempt':'Open quiz'}</button>`}${!locked?`<button class="button secondary" data-edit-quiz="${item.id}" ${editable?'':'disabled'}>Edit or move</button><button class="button ghost" data-cancel-quiz="${item.id}" ${editable?'':'disabled'}>Cancel</button>`:''}</div></article>`;}).join('')||'<p class="muted">No scheduled quizzes yet. Instant practice below does not reserve calendar time.</p>'}</section>${open.length?`<section class="panel"><h2>Saved attempts</h2>${open.map(a=>{const expired=a.expiresAt&&new Date(a.expiresAt)<=new Date();return `<button class="resource-row" data-attempt="${a.id}">${icon('quiz')}<span><strong>${expired?'Expired timed attempt':a.expiresAt?'Timed attempt · clock continues':'Untimed practice'}</strong><small>${Object.keys(a.answers).length}/${a.questions.length} answered${a.expiresAt?` · deadline ${new Date(a.expiresAt).toLocaleString('en-IN')}`:' · resume at your pace'}</small></span>${icon('arrow')}</button>`;}).join('')}</section>`:''}<div class="two-column"><section class="panel"><h2>Instant practice</h2><form id="quiz-builder" class="stack"><fieldset class="quiz-topics"><legend>Covered topics</legend>${topics.map(t=>`<label class="checkbox"><input type="checkbox" name="topics" value="${esc(t)}" checked>${esc(t)}</label>`).join('')||'<p class="muted">Complete a lesson or problem to unlock its topic.</p>'}</fieldset><div class="form-grid"><label class="field">Difficulty<select name="difficulty"><option>Beginner</option><option>Intermediate</option></select></label><label class="field">Time limit<select name="minutes"><option value="0">Untimed · pause freely</option><option value="10">10 minutes</option><option value="20">20 minutes</option><option value="30">30 minutes</option></select></label></div><p class="form-help">Answers save as you go. A timed quiz continues counting down after you leave. At expiry, unanswered questions count as skipped; empty attempts receive no score.</p><button type="submit" class="button primary" ${topics.length&&editable?'':'disabled'}>Start practice ${icon('arrow')}</button><div class="form-error" hidden role="alert"></div></form></section><section class="panel"><h2>Recent results</h2>${attempts.filter(a=>a.status==='submitted').reverse().slice(0,5).map(a=>`<button class="resource-row" data-attempt="${a.id}">${icon('today')}<span><strong>${a.result.percent}% · ${a.result.correct}/${a.result.total} correct</strong><small>${new Date(a.submittedAt).toLocaleDateString('en-IN')} · ${a.result.skipped} skipped</small></span>${icon('arrow')}</button>`).join('')||'<p class="muted">Results appear here after you submit a quiz.</p>'}</section></div>`;
