function openDialog(title,body,footer=''){
 if(navigationRunning)return;
 document.querySelector('dialog')?.remove();dialogReturn=document.activeElement;
 const d=document.createElement('dialog');d.className='dialog';d.setAttribute('aria-labelledby','dialog-title');d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-button" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;document.body.append(d);
 d.addEventListener('close',()=>{d.remove();if(dialogReturn?.isConnected)dialogReturn.focus();else document.querySelector('#page')?.focus({preventScroll:true});});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});d.showModal();restoreFormDraft(d.querySelector('form'));if(store.getJourney()?.status!=='active'&&ui.workspace==='learning'&&d.querySelector('#item-form,#schedule-form,#reschedule-form,#schedule-quiz-form'))d.querySelectorAll('form input,form textarea,form select,form button').forEach(el=>el.disabled=true);
}
