function safeUrl(value){try{const url=new URL(value);return ['https:','http:'].includes(url.protocol)?url.href:'';}catch(_){return '';}}
function openItem(id,taskId=''){
 const j=store.getJourney(),item=j?.items.find(i=>i.id===id);if(!item){notice('This item is not part of the selected journey.');return;}
 if(item.type==='quiz'){const previous=store.getData().attempts.find(a=>a.journeyId===j.id&&a.itemId===id&&a.status!=='abandoned');if(previous){ui.quizId=previous.id;ui.page='Quizzes';render(true);return;}openScheduledQuiz(item);return;}
 const tasks=store.getTasks().filter(t=>t.itemId===id),reference=item.studyReference&&store.getWorkspace().courses.find(c=>c.id===item.studyReference.courseId),task=tasks.find(t=>t.id===taskId),remaining=tasks.filter(t=>!t.completedAt),evidence=store.getData().evidence.filter(e=>e.itemId===id&&e.journeyId===j.id),url=safeUrl(item.sourceUrl),editable=j.status==='active';
 openDialog(task?`${item.title} · session`:item.title,`<div class="chips">${badge(item.type==='problem'?'Practice problem':'Learning item','green')}${badge(item.topic)}${badge(duration(task?.minutes||item.duration))}${item.completedAt?badge('Completed','green'):''}</div>${task?`<p><strong>${formatDate(task.date)} · ${task.startTime}–${task.endTime}</strong>${task.completedAt?' · Completed':''}</p>`:''}<p class="muted">${esc(item.description)}</p>${reference?`<button class="button secondary" data-study-course="${reference.id}" ${item.studyReference.materialId?`data-study-material="${item.studyReference.materialId}"`:`data-study-assignment="${item.studyReference.assignmentId}"`}>Open official coursework</button><p class="form-help">This is private preparation. Completing it does not submit or complete official coursework.</p>`:item.studyReference?'<p class="form-help">This private preparation record is preserved. The source course is no longer available in your current access.</p>':''}${item.content?`<div class="lesson-content">${esc(item.content).split('\n').map(p=>`<p>${p}</p>`).join('')}</div>`:''}${url?`<a class="button secondary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${icon('external')} Open ${item.type==='problem'?'problem source':'resource'}</a>`:''}<p class="form-help">${task?'Complete this scheduled session to record only its allocated work.':'Completing the whole item also completes every remaining scheduled session.'} Manual records describe your own completion; source links are evidence, not verified results.</p><form id="item-form" data-item-id="${id}" ${task?`data-task-id="${task.id}"`:''} class="stack"><label class="field">Learning note<textarea name="note" maxlength="2000" rows="3">${esc(item.note||'')}</textarea></label><label class="field">Evidence link (optional)<input type="url" name="url" placeholder="https://…" value="${esc(evidence.at(-1)?.url||'')}"></label><div class="form-error" hidden role="alert"></div><div class="actions">${!item.completedAt&&(!task||!task.completedAt)?`<button type="submit" class="button primary" ${editable?'':'disabled'}>${icon('check')} ${task?'Complete this session':`Complete item and ${remaining.length} remaining sessions`}</button>`:item.completedAt?`<button type="button" class="button secondary" data-reopen="${id}" ${editable?'':'disabled'}>Reopen item</button>`:''}<button type="button" class="button ghost" data-save-note="${id}" ${editable?'':'disabled'}>Save note</button>${task&&!item.completedAt?`<button type="button" class="button ghost" data-finish-item="${id}" ${editable?'':'disabled'}>Complete the whole item…</button>`:''}</div></form>${task&&!task.completedAt&&!task.fixed?`<button class="button secondary" data-reschedule="${task.id}" ${editable?'':'disabled'}>Reschedule this session</button>`:''}${tasks.length?`<details ${task?'':'open'}><summary>All ${tasks.length} sessions for this item</summary>${tasks.map(t=>`<div class="resource-row"><span><strong>${formatDate(t.date)} · ${t.startTime}–${t.endTime}</strong><small>${duration(t.minutes)}${t.fixed?' · Fixed':''}${t.completedAt?' · Completed':''}</small></span><button class="button ghost" data-item="${id}" data-task-id="${t.id}">Open session</button></div>`).join('')}</details>`:''}${evidence.length?`<details><summary>Completion evidence</summary>${evidence.map(e=>`<p class="muted">${esc(e.sourceLabel||e.source)} · ${new Date(e.completedAt).toLocaleString('en-IN')}</p>`).join('')}</details>`:''}`);
}
