document.addEventListener('keydown',event=>{if(event.key==='Tab'&&ui.menu&&matchMedia('(max-width:980px)').matches){const focusable=[...document.querySelectorAll('.sidebar button,.sidebar a,.sidebar select')].filter(e=>!e.disabled);const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}if(event.key==='Escape'&&ui.menu){ui.menu=false;render();document.querySelector('.mobile-menu')?.focus();}});
window.addEventListener('popstate',queueNavigation);
window.addEventListener('hashchange',queueNavigation);
async function boot(){
 const ready=await window.learnioReady;if(!ready.ok)return;ui.month=store.today().slice(0,7);
 ui.auth=location.hash==='#register'?'register':'login';
 if(store.getUser()){initializeNavigation();const entry=history.state?.learnioNavigation;if(navigationEntryValid(entry)&&entry.hash===location.hash)Object.assign(ui,navigationView(entry.view));await restoreRoute();}
render(false,true);
const persistence=store.getPersistence();if(persistence.error)notice(persistence.error);
}
boot();

function saveSidebarPreferences(){try{localStorage.setItem('learnio.sidebar',JSON.stringify({width:ui.sidebarWidth,collapsed:ui.sidebarCollapsed}));}catch(_){/* Layout still works when storage is unavailable. */}}
function applySidebarLayout(){
 const mobile=matchMedia('(max-width: 980px)').matches,shell=document.querySelector('.shell'),handle=document.querySelector('.sidebar-resizer');
 if(!shell)return;
 shell.style.setProperty('--sidebar-width',`${clampSidebarWidth(ui.sidebarWidth)}px`);shell.classList.toggle('sidebar-collapsed',ui.sidebarCollapsed===true);
 const toggle=document.querySelector('.sidebar-toggle'),label=mobile?'Close navigation':ui.sidebarCollapsed?'Expand sidebar':'Collapse sidebar';
 if(toggle){toggle.setAttribute('aria-label',label);toggle.setAttribute('title',label);toggle.setAttribute('aria-expanded',String(mobile?ui.menu:!ui.sidebarCollapsed));}
 document.querySelector('.mobile-menu')?.setAttribute('aria-expanded',String(mobile&&ui.menu));
 if(handle)handle.setAttribute('aria-valuenow',String(clampSidebarWidth(ui.sidebarWidth)));
}
function resizeSidebar(value){ui.sidebarWidth=clampSidebarWidth(value);applySidebarLayout();}
document.addEventListener('pointerdown',event=>{
 const handle=event.target.closest('.sidebar-resizer');if(!handle||event.button!==0||matchMedia('(max-width: 980px)').matches||ui.sidebarCollapsed)return;
 event.preventDefault();const startX=event.clientX,startWidth=ui.sidebarWidth;handle.setPointerCapture(event.pointerId);document.body.classList.add('sidebar-resizing');
 const move=e=>{if(e.pointerId===event.pointerId)resizeSidebar(startWidth+e.clientX-startX);};
 const finish=e=>{if(e.pointerId!==event.pointerId)return;handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',finish);handle.removeEventListener('pointercancel',finish);handle.removeEventListener('lostpointercapture',finish);document.body.classList.remove('sidebar-resizing');saveSidebarPreferences();};
 handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',finish);handle.addEventListener('pointercancel',finish);handle.addEventListener('lostpointercapture',finish);
});
document.addEventListener('keydown',event=>{
 if(!event.target.matches('.sidebar-resizer'))return;
 const widths={ArrowLeft:ui.sidebarWidth-10,ArrowRight:ui.sidebarWidth+10,Home:220,End:400};if(!(event.key in widths))return;
 event.preventDefault();resizeSidebar(widths[event.key]);saveSidebarPreferences();
});
function syncMobileNavigation(){const mobile=matchMedia('(max-width: 980px)').matches;const sidebar=document.querySelector('.sidebar'),main=document.querySelector('.main-area');if(sidebar)sidebar.inert=mobile&&!ui.menu;if(main)main.inert=mobile&&ui.menu;document.body.classList.toggle('menu-open',mobile&&ui.menu);}
matchMedia('(max-width: 980px)').addEventListener('change',()=>{ui.menu=false;document.querySelector('.shell')?.classList.remove('menu-open');applySidebarLayout();syncMobileNavigation();});

function courseSelector(){
 if(ui.workspace==='course'||!ui.courseId)return '';
 const courses=(store.getWorkspace().courses||[]).filter(c=>ui.workspace==='studio'?!c.institutionId&&c.ownerId===store.getUser().id:c.institutionId===ui.institutionId);
 if(!courses.length)return '';
 const terms=store.getWorkspace().semesters||[];
 return `<div class="journey-selector"><label class="sidebar-label" for="course">COURSE CONTEXT</label><select id="course"><option value="">${ui.workspace==='studio'?'All teaching':'College overview'}</option>${courses.map(c=>`<option value="${c.id}" ${ui.courseId===c.id?'selected':''}>${esc(c.title)}${ui.workspace==='institution'?' · '+esc(terms.find(s=>s.id===c.semesterId)?.title||'Unassigned'):''}</option>`).join('')}</select></div>`;
}

function activityPanel(activity){
 const currentYear=Number(activity.today.slice(0,4)),years=[...new Set([...activity.availableYears,...Array.from({length:5},(_,i)=>currentYear-i),activity.year])].sort((a,b)=>b-a);
 const offset=new Date(`${activity.startDate}T00:00:00Z`).getUTCDay(),columns=Math.ceil((offset+activity.days.length)/7),months=Array.from({length:12},(_,i)=>{const date=`${activity.year}-${String(i+1).padStart(2,'0')}-01`,index=activity.days.findIndex(d=>d.date===date);return {label:formatDate(date,{month:'short'}),column:Math.floor((offset+index)/7)+1};});
 const selected=activity.days.find(d=>d.date===ui.activityDate&&!d.future)||activity.days.find(d=>d.date===activity.today)||[...activity.days].reverse().find(d=>!d.future)||activity.days[0];
 const summary=d=>`${formatDate(d.date,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}: ${d.count} learning ${d.count===1?'event':'events'} · ${duration(d.minutes)} estimated completed workload`;
 return `<section class="panel consistency-panel"><div class="panel-head"><div><p class="eyebrow">ACTUAL CALENDAR ACTIVITY</p><h2>Learning consistency</h2><p>Every square is a day. Every shade is a small step forward.</p></div><label class="field year-select">Year<select id="activity-year">${years.map(year=>`<option value="${year}" ${year===activity.year?'selected':''}>${year}</option>`).join('')}</select></label></div><div class="calendar-scroll" role="region" aria-label="Annual learning activity calendar"><div class="contribution-calendar" style="--weeks:${columns}"><div class="contribution-months" aria-hidden="true">${months.map(m=>`<span style="grid-column:${m.column}">${m.label}</span>`).join('')}</div><div class="contribution-body"><div class="contribution-weekdays" aria-hidden="true"><span></span><span>Mon</span><span></span><span>Wed</span><span></span><span>Fri</span><span></span></div><div class="contribution-grid" role="group" aria-label="${activity.year} daily learning events. Use arrow keys to move between days.">${Array.from({length:offset},()=>'<span class="contribution-spacer" aria-hidden="true"></span>').join('')}${activity.days.map(d=>`<button type="button" class="contribution-cell level-${d.level}${d.future?' future':''}${d.date===activity.today?' today':''}" data-activity-date="${d.date}" data-summary="${esc(summary(d))}" tabindex="${d.date===selected.date?0:-1}" aria-label="${esc(d.future?`${formatDate(d.date,{day:'numeric',month:'long',year:'numeric'})}: future date`:summary(d))}" aria-pressed="${d.date===selected.date}" title="${esc(d.future?'Future date':summary(d))}" ${d.future?'disabled':''}></button>`).join('')}</div></div></div></div><label class="field activity-date-picker">Inspect a day<input type="date" id="activity-date-picker" min="${activity.startDate}" max="${activity.year===currentYear?activity.today:`${activity.year}-12-31`}" value="${selected.date}"></label><div class="activity-footer"><p id="activity-day-detail" class="activity-day-detail" aria-live="polite">${esc(summary(selected))}</p><div class="contribution-legend" aria-label="Intensity: 0, 1, 2 to 3, 4 to 5, 6 or more learning events"><span>Less</span>${[0,1,2,3,4].map(level=>`<i class="level-${level}" aria-hidden="true"></i>`).join('')}<span>More</span></div></div><p class="form-help">${activity.activeDays} active ${activity.activeDays===1?'day':'days'} · ${activity.totalEvents} learning ${activity.totalEvents===1?'event':'events'} in ${activity.year} · ${esc(activity.timezone)}. Includes saved completions and submitted personal quizzes. Sample data and corrected completions are excluded.</p></section>`;
}
function selectActivityDay(cell){
 ui.activityDate=cell.dataset.activityDate;
 document.querySelectorAll('[data-activity-date]').forEach(el=>{el.tabIndex=el===cell?0:-1;el.setAttribute('aria-pressed',String(el===cell));});
 const detail=document.querySelector('#activity-day-detail');if(detail)detail.textContent=cell.dataset.summary;const picker=document.querySelector('#activity-date-picker');if(picker)picker.value=cell.dataset.activityDate;
}
document.addEventListener('focusin',event=>{if(event.target.matches('[data-activity-date]'))selectActivityDay(event.target);});
document.addEventListener('keydown',event=>{
 const cell=event.target.closest('[data-activity-date]');if(!cell)return;
 const cells=[...document.querySelectorAll('[data-activity-date]:not(:disabled)')],index=cells.indexOf(cell),moves={ArrowUp:-1,ArrowDown:1,ArrowLeft:-7,ArrowRight:7};let target=index;
 if(event.key in moves)target=Math.max(0,Math.min(cells.length-1,index+moves[event.key]));else if(event.key==='Home')target=0;else if(event.key==='End')target=cells.length-1;else return;
 event.preventDefault();cells[target]?.focus();
});

function navigationView(view=ui){
 const keys=['previewCourse','replyParent','academyTab','assessmentFilter','selectedAssignment','selectedCourseQuiz','selectedCourseAttempt','selectedSubmission','gradingFilter','gradingAssignment','gradingSourceCourseId','gradingQueueIds','learningMaterialId','resultsView','ownedContentType','academicSetupTab','peopleTab','scheduleView','academyEditor','setupEntryId','quizReturnPage','page','workspace','query','filters','month','quizId','courseId','institutionId','planJourney','planWeek','planDetailed','activityYear','activityDate','progressJourney','progressAttempt','collegeInstitution','collegeSemester','collegeCourseView','collegeMonth','noticeCategory','noticeStatus','noticeQuery','academicYear','academicSemester','academicCourse','academicStatus','academicView'];
 return JSON.parse(JSON.stringify(Object.fromEntries(keys.map(key=>[key,view[key]??null]))));
}
function resetAccountView(){for(const key of Object.keys(navigationView()))ui[key]=null;Object.assign(ui,{page:'Today',workspace:'learning',auth:'login',menu:false,query:'',filters:{},month:store.today().slice(0,7),quizId:null,courseId:''});}
function navigationSignature(hash,view){
 const keys=view.workspace==='institution'?({Schedule:['collegeMonth'],Calendar:['collegeMonth'],Courses:['collegeSemester','collegeCourseView'],'My teaching':['collegeSemester','collegeCourseView'],Academics:['academicYear','academicSemester','academicCourse','academicStatus','academicView'],'Academic profile':['academicYear','academicSemester','academicCourse','academicStatus','academicView'],Announcements:['noticeCategory','noticeStatus','noticeQuery']}[view.page]||['previewCourse','replyParent','academyTab','assessmentFilter','selectedAssignment','selectedCourseQuiz','selectedCourseAttempt','selectedSubmission','gradingFilter','gradingAssignment','learningMaterialId','resultsView','ownedContentType','academicSetupTab','peopleTab','scheduleView']):({Calendar:['month','filters'],'Journey plan':['planJourney','planWeek','planDetailed'],Discover:['query','filters'],Practice:['query','filters'],Progress:['activityYear','progressAttempt']}[view.page]||['assessmentFilter','selectedAssignment','selectedCourseQuiz','selectedSubmission','learningMaterialId','resultsView','ownedContentType']);
 return JSON.stringify([hash,...keys.map(key=>view[key])]);
}
function saveNavigation(){try{sessionStorage.setItem('learnio.navigation',JSON.stringify(navigationState));}catch(_){/* History still works when browser storage is unavailable. */}}
function resetNavigation(){
 navigationState={userId:store.getUser()?.id||null,session:crypto.randomUUID(),index:0,end:0};saveNavigation();navigationLocation='';
}
function initializeNavigation(){
 let saved;try{saved=JSON.parse(sessionStorage.getItem('learnio.navigation'));}catch(_){}
 const entry=history.state?.learnioNavigation,userId=store.getUser()?.id;
 if(saved?.userId===userId&&entry?.userId===userId&&saved.session===entry.session&&Number.isSafeInteger(saved.end)&&Number.isSafeInteger(entry.index)&&entry.index>=0&&saved.end>=entry.index){navigationState={userId,session:entry.session,index:entry.index,end:saved.end};}
 else resetNavigation();
}
function navigationEntryValid(entry){return !!entry&&entry.userId===store.getUser()?.id&&entry.session===navigationState.session&&Number.isSafeInteger(entry.index)&&entry.index>=0&&entry.index<=navigationState.end;}
function navigationControls(){
 return `<nav class="history-controls" aria-label="Navigation history"><button type="button" class="icon-button history-back" data-action="navigation-back" aria-label="Back" title="Back" ${navigationRunning||navigationState.index===0?'disabled':''}>${icon('arrow')}</button><button type="button" class="icon-button" data-action="navigation-forward" aria-label="Forward" title="Forward" ${navigationRunning||navigationState.index>=navigationState.end?'disabled':''}>${icon('arrow')}</button></nav>`;
}
function updateNavigationControls(){
 const shell=document.querySelector('.shell');if(shell)shell.inert=navigationRunning;
 const back=document.querySelector('[data-action="navigation-back"]'),forward=document.querySelector('[data-action="navigation-forward"]');
 if(back)back.disabled=navigationRunning||navigationState.index===0;
 if(forward)forward.disabled=navigationRunning||navigationState.index>=navigationState.end;
}
function writeRoute(replace=false){
 if(navigationState.userId!==store.getUser()?.id||!navigationState.session)initializeNavigation();
 const params=new URLSearchParams();
 if(ui.workspace!=='learning')params.set('workspace',ui.workspace);else if(store.getJourney())params.set('journey',store.getJourney().id);
 if(ui.institutionId&&ui.workspace==='institution')params.set('institution',ui.institutionId);
 if(ui.courseId&&ui.workspace!=='learning')params.set('course',ui.courseId);
 if(ui.quizId&&ui.workspace==='learning')params.set('attempt',ui.quizId);
 for(const [key,param,pages] of [['selectedAssignment','assignment',['Assessments']],['selectedCourseQuiz','quiz',['Assessments']],['selectedSubmission','submission',['Results']],['selectedCourseAttempt','quizAttempt',['Results','Assessments']],['learningMaterialId','material',['Learning','Materials']],['setupEntryId','entry',['Journey setup']]])if(ui[key]&&pages.includes(ui.page))params.set(param,ui[key]);
 const hash=`#${encodeURIComponent(ui.page)}${params.size?'?'+params:''}`,view=navigationView(),current=history.state?.learnioNavigation;
 const push=!replace&&navigationEntryValid(current)&&navigationSignature(current.hash,current.view)!==navigationSignature(hash,view);
 if(push){navigationState.index=current.index+1;navigationState.end=navigationState.index;}
 const entry={userId:navigationState.userId,session:navigationState.session,index:navigationState.index,hash,view};
 history[push?'pushState':'replaceState']({...history.state,learnioNavigation:entry},'',hash);saveNavigation();
 navigationLocation=`${hash}|${entry.session}|${entry.index}`;
 if(!accountScope()&&!['Editor','Journey setup'].includes(ui.page))try{localStorage.setItem(`learnio.last.${store.getUser().id}`,hash);}catch(_){}
 if(navigationRunning&&!replace)navigationPending={hash,entry};
}
function queueNavigation(){
 const current=history.state?.learnioNavigation,marker=`${location.hash}|${current?.session||''}|${current?.index??''}`;
 if(marker===navigationLocation)return navigationDrain||Promise.resolve();
 navigationLocation=marker;navigationPending={hash:location.hash,entry:current};closeDialog();ui.menu=false;
 if(navigationRunning)return navigationDrain;
 navigationRunning=true;updateNavigationControls();
 navigationDrain=(async()=>{
  try{
   while(navigationPending){
    const target=navigationPending;navigationPending=null;const userId=store.getUser()?.id;
    let writes;do{writes=store.whenIdle();await writes;}while(writes!==store.whenIdle());
    if(navigationPending)continue;
    if(store.getUser()?.id!==userId){render(true,true);continue;}
    if(!userId){ui.auth=target.hash==='#register'?'register':'login';authPage();continue;}
    if(navigationEntryValid(target.entry)&&target.entry.hash===target.hash){navigationState.index=target.entry.index;Object.assign(ui,navigationView(target.entry.view));}
    else if(target.entry){resetNavigation();}
    else{navigationState.index++;navigationState.end=navigationState.index;}
    await restoreRoute(target.hash);
    if(navigationPending||location.hash!==target.hash||store.getUser()?.id!==userId)continue;
    render(true,true);
   }
  }catch(error){notice(error.message||'This page could not be restored.');}
  finally{navigationRunning=false;navigationDrain=null;updateNavigationControls();}
 })();return navigationDrain;
}
async function restoreRoute(hash=location.hash){
 const userId=store.getUser()?.id;
 const [rawPage,query='']=hash.slice(1).split('?'),params=new URLSearchParams(query),workspace=params.get('workspace');
 ui.routeError='';
 ui.workspace=workspace==='studio'&&store.getUser().educator?'studio':workspace==='institution'?'institution':workspace==='course'?'course':'learning';
 const institutions=store.getWorkspace().institutions||[];
 const requestedInstitution=params.get('institution');ui.institutionId=requestedInstitution?institutions.find(i=>i.id===requestedInstitution)?.id:institutions[0]?.id;
 if(ui.workspace==='institution'&&!ui.institutionId){ui.workspace='learning';ui.routeError='This institution is not available to your account.';}
 const course=(store.getWorkspace().courses||[]).find(c=>c.id===params.get('course')&&(ui.workspace==='studio'?!c.institutionId&&c.ownerId===store.getUser().id:ui.workspace==='institution'?c.institutionId===ui.institutionId:ui.workspace==='course'?!c.institutionId&&c.learnerIds.includes(store.getUser().id):false));
 ui.courseId=course?.id||'';
 if(params.get('course')&&!course){ui.routeError='This course is not available in the requested workspace.';if(ui.workspace==='course')ui.workspace='learning';}
 const attempt=store.getAttempt(params.get('attempt')),journeyId=params.get('journey')||attempt?.journeyId;
 if(ui.workspace==='learning'&&journeyId&&journeyId!==store.getJourney()?.id){if(store.getJourney(journeyId)){const result=await store.selectJourney(journeyId);if(!result.ok)ui.routeError=result.error;}else ui.routeError='This journey is not available to your account.';}
 if(store.getUser()?.id!==userId)return;
 let page;try{page=decodeURIComponent(rawPage);}catch(_){page='Today';}
 const allowed=[...accountPages,...navigation().flatMap(([,pages])=>pages.map(([p])=>p)),...(ui.workspace==='learning'?['Journey setup']:['Results','Assessments','Institution resources']),'Editor'];
 const canonical=canonicalPage(page);ui.page=allowed.includes(canonical)?canonical:navigation()[0][1][0][0];
 if(ui.workspace!=='learning'&&page==='Assignments')ui.assessmentFilter='all';if(ui.workspace!=='learning'&&page==='Quizzes')ui.assessmentFilter='all';
 if(page==='Certificates')ui.resultsView='records';if(page==='Grades')ui.resultsView='scores';
 if(['Students','Educators','New enrollment','User groups'].includes(page))ui.peopleTab=({Students:'Students',Educators:'Educators','New enrollment':'New enrollment','User groups':'User groups'})[page];
 if(['Semesters','Departments','Programs'].includes(page))ui.academicSetupTab=page;
 for(const [key,param] of [['selectedAssignment','assignment'],['selectedCourseQuiz','quiz'],['selectedSubmission','submission'],['selectedCourseAttempt','quizAttempt'],['learningMaterialId','material'],['setupEntryId','entry']])ui[key]=params.get(param)||null;
 if(ui.setupEntryId&&!store.catalogue.some(c=>c.id===ui.setupEntryId))ui.setupEntryId=null;
 ui.quizId=attempt&&attempt.journeyId===store.getJourney()?.id?attempt.id:null;
}

function enrollmentImportCsv(form){
 if(form.elements.advanced?.checked)return form.elements.csv.value;
 const rows=window.LearnioCSV.parse(form.elements.csv.value),header=rows[0]?.map(v=>v.trim().toLowerCase())||[];if(header.includes('courseid'))throw Error('For one course, use username,role columns. Select Advanced for a multi-course CSV.');
 const username=header.indexOf('username'),role=header.indexOf('role');if(username<0||role<0)throw Error('Use username,role as the CSV header.');
 return window.LearnioCSV.stringify([['username','courseId','role'],...rows.slice(1).map(row=>[row[username]||'',form.elements.courseId.value,row[role]||''])],{formulaSafe:false});
}
function enrollmentImportDialog(){const courses=store.getWorkspace().courses.filter(c=>c.institutionId===ui.institutionId);openDialog('Import course allocations',`<form id="enrollment-import-form" class="stack"><p class="muted">Choose one offering for your cohort. All rows must validate before the batch is saved; existing allocations are skipped.</p><label class="field">Course offering<select name="courseId">${courses.map(c=>`<option value="${c.id}" ${c.id===ui.courseId?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label><label class="checkbox"><input type="checkbox" name="advanced"><span>Advanced: import multiple courses using courseId in each row</span></label><div class="actions">${button('Download matching template','enrollment-template','ghost')}</div><label class="field">CSV file<input id="enrollment-csv-file" type="file" accept=".csv,text/csv"></label><label class="field">CSV content<textarea name="csv" rows="7" required maxlength="100000" placeholder="username,role"></textarea></label><p class="form-help">Single offering: username,role. Advanced: username,courseId,role. Existing accounts only. Roles: student or educator; educator capability is required for teaching. Imports cannot grant administrator rights.</p><div class="form-error" hidden role="alert"></div><div id="import-preview" aria-live="polite"></div><div class="actions"><button type="submit" class="button secondary">Preview allocations</button><button type="button" class="button primary" data-action="commit-enrollments" disabled>Preview before importing</button></div></form>`);}
function downloadCSV(filename,rows){const content=window.LearnioCSV.stringify(rows),url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

function planImportDialog(){openDialog('Import your learning plan',`<form id="plan-import-form" class="stack"><p class="muted">Import personal lessons, problems, or review items. Course names never create an enrollment automatically. Preview all rows before saving.</p><div class="actions">${button('Download CSV template','plan-template','ghost')}</div><label class="field">Journey name<input name="title" required maxlength="80" placeholder="My imported learning plan"></label><label class="field">Start date<input name="startDate" type="date" required value="${dateKey()}"></label><label class="field">CSV file<input id="plan-csv-file" type="file" accept=".csv,text/csv"></label><label class="field">CSV content<textarea name="csv" rows="7" required maxlength="100000" placeholder="type,title,topic,minutes,url"></textarea></label><p class="form-help">Required columns: type, title, topic, minutes, url. Type must be lesson, problem, or review. Optional: date, startTime, fixed. Initial weekly capacity is ${store.defaults.weeklyHours}h; customize it after import.</p><div class="form-error" hidden role="alert"></div><div id="plan-import-preview" aria-live="polite"></div><div class="actions"><button type="submit" class="button secondary">Preview plan</button><button type="button" class="button primary" data-action="commit-plan-import" disabled>Save imported plan</button></div></form>`);}
